# the convention here are α, nux, nuy, \[Pi]yy_Q, \[Pi]zz_Q, \[Pi]xy_Q, \[Pi]B_Q on a prescribed background, the charm
# stress in the components of the medium's \[Pi]yy, \[Pi]zz, \[Pi]xy, \[Pi]B
# background_fields(tau, x, y) = (T, ux, uy, dtT, dxT, dyT, dtux, dxux, dyux, dtuy, dxuy, dyuy)
# as for the medium, \[Pi]xx_Q follows from tracelessness and the tau row from u.pi_Q = 0
# rows 1-3 are the consistent first moment of matrix2d_HQ_BG_consistent!; the second moment is the projected
# divergence of the charm third moment, (D_s/2T) Delta Delta Nabla.S + dM = 0, dM = pi_Q + piB_Q Delta, with the
# corotation term of pi_Q

"""
    matrix2d_HQ_BG_m2!(; background_fields, dmn_eps = 1e-6, α_max = 200.0)
Charm first and second moment on a prescribed 2+1D background, 7 fields (`HQ_2p1d_BG_m2_init`).
"""
function matrix2d_HQ_BG_m2!(; dmn_eps = 1e-6, background_fields, α_max = 200.0)
    (A_i, Source, ϕ, tau, X, params) -> matrix2d_HQ_BG_m2!(A_i, Source, ϕ, tau, X, params;
        dmn_eps = dmn_eps, background_fields = background_fields, α_max = α_max)
end

function matrix2d_HQ_BG_m2!(A_i, Source, ϕ, tau, X, params;
        dmn_eps = 1e-6, background_fields = nothing, α_max = 200.0)

    T, ux, uy, dtT, dxT, dyT, dtux, dxux, dyux, dtuy, dxuy, dyuy = background_fields(tau, X[1], X[2])

    ch = charm_eos(T, clamp(ϕ[1], -α_max, α_max), params.eos.hadron_list)
    Ds = DsT(params.diffusion, T) / T / fmGeV

    # dn/dα + dmn_eps keeps inv(At) regular where n -> 0; it enters kappa = D_s dn/dα too
    At, Ax, Ay, src = two_d_HQ_BG_m2_matrix(ϕ, tau, T, ux, uy, dtT, dxT, dyT, dtux, dxux, dyux, dtuy, dxuy, dyuy,
                                            ch.n, ch.dndT, ch.dnda + dmn_eps, ch.h, ch.dhdT,
                                            ch.I31, ch.dI31dT, ch.dI31da, ch.aQ, ch.bQ, ch.dbQdT, ch.cQ, ch.dcQdT, Ds)

    Ainv = inv(At)
    A_mul_B!(A_i[1], Ainv, Ax)
    A_mul_B!(A_i[2], Ainv, Ay)
    jgemvavx!(Source, Ainv, src)
end


